from pathlib import Path


def replace_once(path: Path, old: str, new: str, label: str) -> None:
    text = path.read_text(encoding='utf-8')
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'{label} anchor count {count}')
    path.write_text(text.replace(old, new, 1), encoding='utf-8')


# Generic command metadata: keep the command layer independent from ContentService
# by storing opaque asset-kind names interpreted only by editor presentation.
header = Path('engine/commands/include/orbit/commands/CommandRegistry.hpp')
replace_once(
    header,
    '''    std::vector<CommandChoice> choices;\n};\n''',
    '''    std::vector<CommandChoice> choices;\n    // Optional project-asset filters for generated editor pickers. Values are\n    // opaque presentation keys (for example "Material" or "Decal"); the\n    // command layer remains independent from the content subsystem.\n    std::vector<std::string> assetKinds;\n};\n''',
    'CommandParameter assetKinds')

registry = Path('engine/commands/src/CommandRegistry.cpp')
replace_once(
    registry,
    '''        if (parameter.defaultValue.has_value() &&\n            !parameter.choices.empty())\n        {\n            const bool defaultIsChoice =\n                std::any_of(\n                    parameter.choices.begin(),\n                    parameter.choices.end(),\n                    [&parameter](const CommandChoice& choice)\n                    {\n                        return choice.value == *parameter.defaultValue;\n                    });\n\n            if (!defaultIsChoice)\n            {\n                throw std::invalid_argument(\n                    "Command parameter default value is not an enumerated choice: " +\n                    parameter.name);\n            }\n        }\n''',
    '''        if (parameter.defaultValue.has_value() &&\n            !parameter.choices.empty())\n        {\n            const bool defaultIsChoice =\n                std::any_of(\n                    parameter.choices.begin(),\n                    parameter.choices.end(),\n                    [&parameter](const CommandChoice& choice)\n                    {\n                        return choice.value == *parameter.defaultValue;\n                    });\n\n            if (!defaultIsChoice)\n            {\n                throw std::invalid_argument(\n                    "Command parameter default value is not an enumerated choice: " +\n                    parameter.name);\n            }\n        }\n\n        if (!parameter.assetKinds.empty() &&\n            parameter.kind != CommandValueKind::String)\n        {\n            throw std::invalid_argument(\n                "Project-asset command parameters must use string values: " +\n                parameter.name);\n        }\n\n        if (!parameter.assetKinds.empty() &&\n            !parameter.choices.empty())\n        {\n            throw std::invalid_argument(\n                "Command parameter cannot combine enumerated choices and project-asset filters: " +\n                parameter.name);\n        }\n\n        std::unordered_set<std::string> assetKinds;\n        for (const std::string& assetKind : parameter.assetKinds)\n        {\n            if (assetKind.empty() ||\n                !assetKinds.insert(assetKind).second)\n            {\n                throw std::invalid_argument(\n                    "Project-asset filters require unique non-empty kind names: " +\n                    parameter.name);\n            }\n        }\n''',
    'CommandParameter asset validation')

